import pandas as pd
from dagster import (
    asset,
    Definitions,
    ConfigurableResource,
    ConfigurableIOManager,
    EnvVar,
    InputContext,
    OutputContext,
)


class WarehouseResource(ConfigurableResource):
    """Injected connection info; secrets come from environment variables."""
    dsn: str

    def query(self, sql: str) -> pd.DataFrame:
        # In real code this would use the dsn to open a connection.
        # Here we return a small fixed frame to keep the example runnable.
        return pd.DataFrame(
            {"order_id": [1, 2, 3], "amount": [10.0, None, 30.0]}
        )


class LocalParquetIOManager(ConfigurableIOManager):
    """Stores each asset as a parquet file keyed by its asset name."""
    base_dir: str = "/tmp/dagster_assets"

    def _path(self, context) -> str:
        return f"{self.base_dir}/{'_'.join(context.asset_key.path)}.parquet"

    def handle_output(self, context: OutputContext, obj: pd.DataFrame) -> None:
        import os
        os.makedirs(self.base_dir, exist_ok=True)
        obj.to_parquet(self._path(context))
        context.add_output_metadata({"rows": len(obj)})

    def load_input(self, context: InputContext) -> pd.DataFrame:
        return pd.read_parquet(self._path(context.upstream_output))


@asset
def raw_orders(warehouse: WarehouseResource) -> pd.DataFrame:
    """Pull raw orders from the warehouse (an injected resource)."""
    return warehouse.query("SELECT order_id, amount FROM orders")


@asset
def clean_orders(raw_orders: pd.DataFrame) -> pd.DataFrame:
    """Depends on raw_orders simply by naming it as a parameter."""
    return raw_orders.dropna(subset=["amount"])


@asset
def order_summary(clean_orders: pd.DataFrame) -> pd.DataFrame:
    """Downstream asset that aggregates clean_orders."""
    return clean_orders.agg(total=("amount", "sum"), count=("amount", "size")).reset_index()


defs = Definitions(
    assets=[raw_orders, clean_orders, order_summary],
    resources={
        "io_manager": LocalParquetIOManager(base_dir="/tmp/dagster_assets"),
        "warehouse": WarehouseResource(dsn=EnvVar("WAREHOUSE_DSN")),
    },
)

